import pytest

from linkvault.validate import (
    RESERVED, ValidationError, parse_clock_request, parse_link_request,
    valid_slug, valid_url)

BAD_URLS = [
    "ftp://x", "javascript:alert(1)", "http://", "http:///x", "http://a b",
    "http://a\tb.com/", "http://a.com/\n", "http://a.com/\x7f", "http://a\x00b/",
    "http://" + "a" * 2042, "http://[::1", "http://a.com/\ud800", "", 5, None,
]
GOOD_URLS = [
    "http://" + "a" * 2041, "HTTP://Example.com/X", "https://é.example/ü?q=1#f",
    "http://h:abc/",
]


@pytest.mark.parametrize("u", BAD_URLS)
def test_bad_urls(u):
    assert valid_url(u) is False


@pytest.mark.parametrize("u", GOOD_URLS)
def test_good_urls(u):
    assert valid_url(u) is True


def test_url_length_boundary():
    assert len("http://" + "a" * 2041) == 2048
    assert len("http://" + "a" * 2042) == 2049


@pytest.mark.parametrize("s", ["ab", "a" * 33, "a b", "abc\n", "ab!", "", "é" * 3, None, 5])
def test_bad_slugs(s):
    assert valid_slug(s) is False


@pytest.mark.parametrize("s", ["abc", "a" * 32, "A_b-9", "healthz"])
def test_good_slugs(s):
    assert valid_slug(s) is True


def test_reserved():
    assert RESERVED == {"healthz"}


U = "http://a.com/"


@pytest.mark.parametrize("body", [
    None, [], "x", {}, {"slug": "abc"}, {"url": U, "x": 1}, {"url": 5},
    {"url": "ftp://x"}, {"url": U, "slug": None}, {"url": U, "slug": "ab"},
    {"url": U, "slug": 5}, {"url": U, "expires_in": None},
    {"url": U, "expires_in": True}, {"url": U, "expires_in": 0},
    {"url": U, "expires_in": 31536001}, {"url": U, "expires_in": 60.0},
    {"url": U, "expires_in": "60"},
])
def test_link_request_rejects(body):
    with pytest.raises(ValidationError):
        parse_link_request(body)


def test_link_request_accepts():
    assert parse_link_request({"url": U}) == (U, None, None)
    assert parse_link_request({"url": U, "slug": "abc", "expires_in": 1}) == (U, "abc", 1)
    assert parse_link_request({"url": U, "expires_in": 31536000}) == (U, None, 31536000)


def test_clock_request_accepts():
    assert parse_clock_request({"now": "2026-01-01T00:00:00Z"}) == 1767225600


@pytest.mark.parametrize("body", [
    {}, {"now": "2026-01-01T00:00:00Z", "x": 1}, {"now": 5}, {"now": "bad"},
    {"now": "2026-02-30T00:00:00Z"}, None, "x",
])
def test_clock_request_rejects(body):
    with pytest.raises(ValidationError):
        parse_clock_request(body)
